import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`product-photo-generator`,hasInputUrl:!1,hasInputFile:!0,heroTitle:`Generate product photos in minutes`,heroSubtitle:`Perplexity Computer analyzes your product, generates studio-quality lifestyle photos, and delivers a full image set — automatically.`,inputFileCta:`Upload your product`,inputFileAccept:`.pdf,.png,.jpg,.jpeg,.webp`,inputFilePrefill:`Analyze the uploaded product image and generate a complete set of professional product photos. 1) Identify the product type, key features, dimensions, and brand aesthetic from the uploaded file. 2) Research top-performing product photography styles for this category across leading ecommerce platforms. 3) Generate 8 studio-quality product photos including: a clean white-background hero shot, 3 lifestyle context shots showing the product in use, 2 detail/close-up shots highlighting texture and craftsmanship, 1 scale reference shot, and 1 flat-lay or group arrangement. 4) For each lifestyle shot, select a scene and lighting setup that matches the product's target audience and price point. 5) Optimize every image for ecommerce — proper aspect ratios for Shopify, Amazon, and social media. 6) Deliver a final package with all 8 images, a shot list describing each photo's use case, and recommended platform placements.`,heroOverlaySteps:[`Analyzing your product image for type, features, and brand aesthetic`,`Researching top-performing photography styles for your product category`,`Generating studio-quality hero, lifestyle, and detail shots`,`Platform-optimized product photos with shot list — ready to publish`],generatingSteps:[`Analyzing the uploaded file to identify product type, features, and aesthetic`,`Designing an agent to research category photography trends and competitor imagery`,`Configuring photo generation for hero shots, lifestyle scenes, and detail close-ups`,`Setting up platform-specific image optimization and deliverable packaging`],featureSectionTitle:`From product image to photo shoot`,featureCardTitles:[`Connects to your ecommerce stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Canva, Google Drive, Airtable, Dropbox Sign — Computer plugs into your tools so product photos flow straight from generation to your storefront.`,`White-background hero shots. Lifestyle context photos. Detail close-ups. Scale references. Platform-optimized sizing for Shopify, Amazon, and social.`],capabilitySectionTitle:`Your photo studio, on autopilot`,capabilitySectionSubtitle:`Upload your product, step away, come back to a full photo shoot.`,capabilityCards:[{title:`Product Analysis`,description:`Computer can identify your product's type, key features, materials, and brand aesthetic — then match it to the photography style that converts best.`},{title:`Lifestyle Scenes`,description:`Computer can generate context-rich lifestyle photos — placing your product in real-world settings matched to your target audience and price point.`},{title:`Detail Shots`,description:`Computer can create close-up and texture shots that highlight craftsmanship, materials, and features buyers need to see before purchasing.`},{title:`Connect Your Tools`,description:`Computer can push finished photos to Shopify, Google Drive, Canva, and Airtable — build workflows across your entire product content pipeline.`},{title:`Brand Memory`,description:`Computer can remember your brand colors, photography style, and past shoots — so every new product gets a consistent visual identity.`},{title:`Seasonal Refreshes`,description:`Computer can monitor your catalog and alert you when listings need fresh seasonal imagery or when new photography trends emerge in your category.`}]});export{t as default};
